def check_no_ap4(coloring):
    n = len(coloring)
    for a in range(1, n + 1):
        for d in range(1, n + 1):
            if a + 3 * d <= n:
                c1 = coloring[a - 1]
                c2 = coloring[a + d - 1]
                c3 = coloring[a + 2 * d - 1]
                c4 = coloring[a + 3 * d - 1]
                if c1 == c2 == c3 == c4:
                    return False, (a, d)
    return True, None

# Let's verify if W(2, 4) is indeed 35.
# Actually, I can just try to solve it for n=41 using a SAT solver.
from pysat.solvers import Glucose3

def solve_van_der_waerden(n, k):
    solver = Glucose3()
    # Variables: x_{i, c} where i is 1..n, c is 0..1
    # x_{i, 0} is variable i, x_{i, 1} is variable i + n
    def var(i, c):
        return (i - 1) * 2 + c + 1

    # Each integer has exactly one color
    for i in range(1, n + 1):
        solver.add_clause([var(i, 0), var(i, 1)])
        solver.add_clause([-var(i, 0), -var(i, 1)])

    # No monochromatic AP of length k
    for a in range(1, n + 1):
        for d in range(1, n + 1):
            if a + (k - 1) * d <= n:
                # For each color c, not all elements in the AP have color c
                for c in range(2):
                    solver.add_clause([-var(a + j * d, c) for j in range(k)])

    if solver.solve():
        return [0 if solver.get_model()[i-1] > 0 else 1 for i in range(1, n + 1)]
    else:
        return None

result = solve_van_der_waerden(41, 4)
print(result)
